                console.warn('  ⚠️  cancel of stale run ' + r.id +
                             ' failed: ' + (e2.message || e2));
            }
        });
        return cancelled;
    } catch (e) {
        // Fail OPEN: a stale-cancel probe error must not wedge the arm —
        // worst case is the wasted runs we are trying to prevent.
