                ] };
            }
            return undefined;
        }
    }));
    sm.action({ jobParams: { owner: 'IstiN', repo: 'flutter_agent_harness',
        ciWorkflow: 'ci.yml', rules: [RULES.validate] } });

    var cancels = sm.capturedCliCommands.filter(function (c) {
