                   r.head_sha !== currentSha &&
                   (r.status === 'queued' || r.status === 'in_progress' ||
                    r.status === 'waiting' || r.status === 'pending');
        });
        var cancelled = 0;
        stale.forEach(function (r) {
            try {
                cli_execute_command({
                    command: 'gh api -X POST repos/' +
                        repoInfo.owner + '/' + repoInfo.repo +
                        '/actions/runs/' + r.id + '/cancel || true'
