// null when the head SHA is unknown — nothing to record.
function redHeadMarkerLine(priorReds, headSha, cap) {
    if (!headSha) return null;
    return '\uD83D\uDD34 red head ' + headSha + ' \u2014 red ' + (priorReds + 1) + '/' + cap +
