        var sm = makeSmAgent(Object.assign(config('a', 'b'), { github: { items: [prItem(9)] } }));
        sm.action({ jobParams: { owner: 'a', repo: 'b', rules: [RULES.update] } });
        assert.equal(sm.capturedCliCommands.length, 0, 'no command without a branch name');
