        return c.command.indexOf('workflow run ci.yml') !== -1; });
    assert.equal(dispatch.length, 1, 'arm still proceeds after the cleanup');
    assert.equal(sm.capturedPrLabelAdds.length, 1, 'ai_validating armed');
});

