// ── One comment read per fail (review #703 💡) ────────────────────────────
// ──
// fail_validation needs TWO marker kinds before its arm decision —
// this PR's red-head counts and the empty-lap counts — and each had
// its own github_get_pr_comments reader (four fetches per fail after
// the rebase). THIS reader fetches the PR comment list ONCE and parses
// every marker kind from the same payload:
// { redHeads: { <headSha>: <highest recorded N> },
//   emptyLaps: { <headSha>: <highest recorded N> }.
// Probe failure fails OPEN (empty state → arm): a broken comment read
// must not strand a red head that these caps exist to un-stall — the
// next red re-reads and re-evaluates.
function failMarkerState(repoInfo, prNumber) {
    var out = { redHeads: {}, emptyLaps: {}, zombies: {} };
    var bodies = [];
    try {
        var raw = github_get_pr_comments({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            pullRequestId: prNumber
        });
        var obj = typeof raw === 'string' ? JSON.parse(raw) : (raw || []);
        var list = Array.isArray(obj) ? obj : (obj.comments || obj.items || []);
        list.forEach(function (c) {
            var body = String((c && c.body) || '');
            bodies.push(body);
            var m;
            RED_HEAD_MARKER_RE.lastIndex = 0;
            while ((m = RED_HEAD_MARKER_RE.exec(body)) !== null) {
                var rn = parseInt(m[2], 10) || 0;
                if (!out.redHeads[m[1]] || rn > out.redHeads[m[1]]) out.redHeads[m[1]] = rn;
            }
            EMPTY_LAP_MARKER_RE.lastIndex = 0;
            while ((m = EMPTY_LAP_MARKER_RE.exec(body)) !== null) {
                var ln = parseInt(m[1], 10) || 0;
                if (!out.emptyLaps[m[3]] || ln > out.emptyLaps[m[3]]) out.emptyLaps[m[3]] = ln;
            }
        });
    } catch (eMarks) {
        console.warn('  ⚠️  fail-marker state read failed: ' + (eMarks.message || eMarks));
    }
    // gh-821 zombie re-dispatch bookkeeping (js/common/validationLiveness.js):
    // parsed from the SAME single comment fetch — per-head re-dispatch counts
    // (crash-loop cap) and the newest marker's timestamp (1/head/hour bound).
    // A read failure above leaves {} — the zombie branch then treats the head
    // as never-re-dispatched (one bounded extra dispatch worst case).
    try {
        out.zombies = validationLivenessModule.zombieMarks(bodies);
    } catch (eZomb) {
        console.warn('  ⚠️  zombie-marker parse failed: ' + (eZomb.message || eZomb));
    }
    return out;
}

// ── gh-807 verdict reconciliation helpers ───────────────────────────────────
//
// Live fa PR #1428 (2026-10-09): two review legs concluded on the SAME head
// 97s apart with contradictory verdicts (APPROVE 05:47:30Z, REQUEST_CHANGES
// 05:47:40Z) and both side effects stuck — pr_approved + agent:rework
// coexisting. The review legs now stamp machine-parseable verdict records
// (js/common/reviewVerdicts.js marker comments); these helpers are the tick
// side: reconcile the labels (AC2) and bind the arming side to the same
// sticky-approval rule the rework side enforces (AC3). Everything fails
// OPEN: a PR without records (pre-gh-807) or a broken read keeps today's
// behavior — reconciliation must never strand a leg.

// Fetches the PR's head sha + current labels in one github_get_pr call
// (labels ride the REST body, same as the query path's prStatus). Returns
// { headSha, labels } or null when the probe fails — callers fail open.
function prHeadAndLabels(repoInfo, prNumber) {
    try {
        var raw = github_get_pr({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            pullRequestId: String(prNumber)
        });
        var pr = (typeof raw === 'string') ? JSON.parse(raw) : (raw || {});
        if (!pr || pr.message || !pr.head || !pr.head.sha) return null;
