 * joins lines; count/cap are meaningless here (a head is cancelled once).
 */
function staleCancelMarkerLine(headSha, atIso) {
    return '\uD83D\uDED1 stale-cancel ' + headSha +
        ' \u2014 stale base at ' + (atIso || '');
}

