        // gh-755 parity: the bookkeeping must not feed verdict machinery.
        var line = live.staleCancelMarkerLine(HEAD, '2026-10-10T18:39:00.000Z');
        assert.deepEqual(live.zombieMarks([line]), {}, 'not a zombie re-dispatch count');
    });
});

